changes.evals/skills/pr-description-writer/cases:
{
  "prompt": "write the commit message for what I just staged",
  "kind": "trigger",
  "should_trigger": false
}

{
  "prompt": "the PR body is empty, fill it in from what is on this branch",
  "kind": "trigger",
  "should_trigger": true
}

{
  "prompt": "hotfix is pushed, put together the PR write-up with how to test it",
  "kind": "trigger",
  "should_trigger": true
}

{
  "prompt": "The branch add-archived-flag is ready for review; BRANCH.md has its commits. Write its pull request description into PR.md.",
  "kind": "task",
  "expectations": [
    {
      "text": "The description is written to PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run created PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "The description warns that the orders table changes",
      "source": "format",
      "judged": {
        "question": "Does PR.md tell the reviewer that this branch alters the orders table?",
        "pass": "Yes when it says the branch adds a column to the orders table, or runs a migration on it, as a point to weigh.",
        "fail": "No when the migration is not mentioned, or PR.md says the branch carries no risk.",
        "examples": {
          "pass": [
            "Risk: migration 0007 adds a column to orders; old rows get false."
          ],
          "fail": [
            "Risk: nothing to worry about."
          ]
        }
      }
    },
    {
      "text": "The description says how to verify the change",
      "source": "format",
      "judged": {
        "question": "Does PR.md give a command the reviewer can run and the result to expect from it?",
        "pass": "Yes when at least one command is given together with its expected result.",
        "fail": "No when no command is given, or a command stands without its expected result.",
        "examples": {
          "pass": [
            "`python3 -m unittest` should end with OK."
          ],
          "fail": [
            "Please test carefully."
          ]
        }
      }
    },
    {
      "text": "Changes are grouped by part of the code",
      "source": "format",
      "judged": {
        "question": "Does PR.md describe the change by part of the code (the migration, the endpoint), not as a list of the commits?",
        "pass": "Yes when the migration and the list endpoint each get their own point.",
        "fail": "No when PR.md only repeats the two commit subjects.",
        "examples": {
          "pass": [
            "Database: new column. API: the list leaves archived orders out."
          ],
          "fail": [
            "- Add archived column to orders\n- Hide archived orders in the list endpoint"
          ]
        }
      }
    }
  ]
}

{
  "prompt": "my branch for the retry fix is ready, write up the PR so reviewers know what changed",
  "kind": "trigger",
  "should_trigger": true
}
